package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import java.security.*;import org.junit.jupiter.api.*;
class FuelPlaneTest {
 static Path out;static Properties input;static byte[] raw;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 static double d(String k){return Double.parseDouble(input.getProperty(k));}
 @BeforeAll static void setup()throws Exception{assertNotNull(System.getenv("FRC_FUEL_PLANE_OUTPUT"));out=Path.of(System.getenv("FRC_FUEL_PLANE_OUTPUT"));raw=Files.readAllBytes(out.resolve("input.properties"));input=new Properties();input.load(new java.io.ByteArrayInputStream(raw));assertEquals("frc-fuel-plane-input/v1",input.getProperty("schema"));assertEquals("blocked",input.getProperty("engineeringAcceptance"));assertEquals("assumed-uniform-solid-sphere",input.getProperty("inertiaBasis"));assertEquals("perfectly-inelastic-unilateral",input.getProperty("normalLaw"));assertEquals(input.getProperty("experimentSha256"),sha(Files.readAllBytes(out.resolve("experiment.json"))));assertEquals(input.getProperty("sourceConfigSha256"),sha(Files.readAllBytes(out.resolve("source-config.json"))));assertEquals(.075,d("radiusM"));assertTrue(d("massKg")>=.20320938176&&d("massKg")<=.226796185);}
 @Test void independentRollingHandVectorBothSigns(){for(int sign:new int[]{-1,1}){var m=new SpherePlane(.2,.075,.2);var s=new SpherePlane.State(0,.075,sign,0,0);double loss=0;for(int i=0;i<50;i++){var r=m.step(s,.02);s=r.state();loss+=r.lossJ();}assertEquals(sign*5./7,s.vx(),1e-12);assertEquals(sign*200./21,s.omega(),1e-11);assertEquals(1./35,loss,1e-12);double t=.1456737447111326;assertEquals(sign*(.5*(1+5./7)*t+5./7*(1-t)),s.x(),1e-12);}}
 @Test void dropTimeAndNormalLossWithZeroFriction(){var m=new SpherePlane(.2,.075,0);var s=new SpherePlane.State(0,.275,1,0,3);double time=0;boolean hit=false;for(int i=0;i<30;i++){var r=m.step(s,.01);time+=.01;if(r.impact()){assertTrue(time>=.20196199771025522&&time-.01<.20196199771025522);assertEquals(.2*SpherePlane.G*.2,r.lossJ(),1e-12);assertEquals(0,r.tangentImpulse());hit=true;}s=r.state();assertEquals(1,s.vx());assertEquals(3,s.omega());}assertTrue(hit);}
 @Test void upwardTouchDepartsThenReturns(){var m=new SpherePlane(.2,.075,.2);var s=new SpherePlane.State(0,.075,0,.05,0);var a=m.step(s,.005);assertFalse(a.impact());assertFalse(a.supported());assertTrue(a.state().z()>.075);var b=m.step(s,.02);assertTrue(b.impact());assertTrue(b.supported());assertEquals(.5*.2*.05*.05,b.lossJ(),1e-12);}
 @Test void downwardTouchImpactsImmediately(){var m=new SpherePlane(.2,.075,0);var r=m.step(new SpherePlane.State(0,.075,0,-1,0),.001);assertTrue(r.impact());assertEquals(.2+.2*SpherePlane.G*.001,r.normalImpulse(),1e-12);assertEquals(.1,r.lossJ(),1e-12);assertEquals(.075,r.state().z());}
 @Test void supportDoesNotCreepAndFrictionlessSlipIsNotRolling(){var m=new SpherePlane(.2,.075,.2);var s=new SpherePlane.State(0,.075,0,0,0);for(int i=0;i<1000;i++){var r=m.step(s,.001);assertFalse(r.impact());assertEquals(.2*SpherePlane.G*.001,r.normalImpulse(),1e-12);assertEquals(0,r.lossJ());assertEquals(s,r.state());s=r.state();}var r=new SpherePlane(.2,.075,0).step(new SpherePlane.State(0,.075,1,0,0),.02);assertEquals("sliding",r.tangentialRegime());assertEquals(1,r.state().vx());assertEquals(0,r.state().omega());}
 @Test void eventAndSlipStopSubdivisionInvariance(){var m=new SpherePlane(.2,.075,.2);for(var start:new SpherePlane.State[]{new SpherePlane.State(0,.0751,1,-1,20),new SpherePlane.State(0,.0750001,1,-.01,14)}){var one=m.step(start,.02);var s=start;double loss=0,pn=0,pt=0;for(int i=0;i<10;i++){var r=m.step(s,.002);s=r.state();loss+=r.lossJ();pn+=r.normalImpulse();pt+=r.tangentImpulse();}assertEquals(one.state().x(),s.x(),1e-12);assertEquals(one.state().vx(),s.vx(),1e-12);assertEquals(one.state().omega(),s.omega(),1e-11);assertEquals(one.lossJ(),loss,1e-12);assertEquals(one.normalImpulse(),pn,1e-12);assertEquals(one.tangentImpulse(),pt,1e-12);assertTrue(one.impact());assertEquals(0,s.vx()-.075*s.omega(),1e-12);}}
 @Test void initialPenetrationAndUnknownInputsReject(){assertThrows(IllegalArgumentException.class,()->new SpherePlane(.2,.075,Double.NaN));var m=new SpherePlane(.2,.075,.2);assertThrows(IllegalArgumentException.class,()->m.step(new SpherePlane.State(0,.074,0,0,0),.001));assertThrows(IllegalArgumentException.class,()->m.step(new SpherePlane.State(0,.075,0,0,0),0));assertThrows(IllegalArgumentException.class,()->m.step(new SpherePlane.State(0,.075,Double.NaN,0,0),.001));}
 @Test void sourceBoundFixtureTraceAndRefinement()throws Exception{var m=new SpherePlane(d("massKg"),d("radiusM"),d("mu"));var initial=new SpherePlane.State(d("xM"),d("zM"),d("vxMps"),d("vzMps"),d("omegaRadps"));var coarse=initial;var fine=initial;double loss=0;double[] max=new double[5];int impacts=0;StringBuilder csv=new StringBuilder("step,xM,zM,vxMps,vzMps,omegaRadps,normalImpulseNs,tangentImpulseNs,lossJ,regime\n");int n=(int)Math.round(d("duration")/d("dt"));assertTrue(n>0&&n<=2000);for(int i=0;i<n;i++){var r=m.step(coarse,d("dt"));coarse=r.state();for(int j=0;j<2;j++)fine=m.step(fine,d("dt")/2).state();double[] a={coarse.x(),coarse.z(),coarse.vx(),coarse.vz(),coarse.omega()},b={fine.x(),fine.z(),fine.vx(),fine.vz(),fine.omega()};for(int j=0;j<5;j++)max[j]=Math.max(max[j],Math.abs(a[j]-b[j]));loss+=r.lossJ();if(r.impact())impacts++;assertEquals(m.energy(initial),m.energy(coarse)+loss,1e-9);csv.append(i).append(',').append(coarse.x()).append(',').append(coarse.z()).append(',').append(coarse.vx()).append(',').append(coarse.vz()).append(',').append(coarse.omega()).append(',').append(r.normalImpulse()).append(',').append(r.tangentImpulse()).append(',').append(r.lossJ()).append(',').append(r.tangentialRegime()).append('\n');}assertEquals(1,impacts);assertTrue(java.util.Arrays.stream(max).allMatch(v->v<1e-9),"Semianalytic subdivision check, not calibration");Files.writeString(out.resolve("trace.csv"),csv,StandardOpenOption.CREATE_NEW);Properties result=new Properties();result.setProperty("inputSha256",sha(raw));result.setProperty("modelClassSha256",sha(SpherePlane.class.getResourceAsStream("SpherePlane.class").readAllBytes()));String[] labels={"maxXDifferenceM","maxZDifferenceM","maxVxDifferenceMps","maxVzDifferenceMps","maxOmegaDifferenceRadps"};for(int j=0;j<5;j++)result.setProperty(labels[j],Double.toString(max[j]));result.setProperty("engineeringAcceptance","blocked");result.setProperty("capture","unsupported");result.setProperty("score","unsupported");try(var stream=Files.newOutputStream(out.resolve("result.properties"),StandardOpenOption.CREATE_NEW)){result.store(stream,"Source-sized sphere, hypothetical plane, uncalibrated rigid law");}}
}
